package ge.opensoft.openservice;
import static ge.opensoft.openservice.Values.*;
import static org.junit.jupiter.api.Assertions.*;
import static com.microsoft.playwright.assertions.PlaywrightAssertions.assertThat;
import com.microsoft.playwright.*;
import com.microsoft.playwright.options.AriaRole;
import java.nio.file.Path;
import java.util.*;
final class CustomerResolutionsBrowserAcceptance {
 static void run(BrowserTest h)throws Exception{
  String id;try(var db=h.store.open()){PlatformFoundationTest.bind(db);Service.createAccount(db,map("name","SolutionBrowserCustomer","role","requester","password",WorkflowSupport.PASSWORD));Service.createAccount(db,map("name","SolutionBrowserAgent","role","agent","password",WorkflowSupport.PASSWORD));String user=RecordAccess.owner(db,"SolutionBrowserCustomer"),group=Service.create(db,"sys_user_group",map("short_description","Resolution support team"),"admin").get("sys_id").toString();db.update("INSERT INTO os_group_member VALUES(?,?)",group,RecordAccess.owner(db,"SolutionBrowserAgent"));String account=CustomerAccounts.save(db,"",map("name","Resolution browser account","group_id",group,"active",true,"revision",0)).get("account_id").toString();CustomerAccounts.manage(db,account,map("operation","contact","username","SolutionBrowserCustomer","active",true,"revision",0));String entitlement=objects(CustomerAccounts.manage(db,account,CustomerCasesAcceptance.entitlement("",0,0)).get("entitlements")).getFirst().get("entitlement_id").toString();db.viewerId=user;db.viewerRole="requester";var item=CustomerCases.create(db,entitlement,map("account_revision",1,"contact_revision",1,"entitlement_revision",1,"summary","Review the checkout solution","description","Checkout needs a resolution","key",Values.id()));id=item.get("sys_id").toString();PlatformFoundationTest.bind(db);Service.update(db,"customer_case",item,map("state","working"),"admin","admin",null);db.connection.commit();}
  try(var p=Playwright.create();var browser=p.chromium().launch();var staffContext=browser.newContext();var customerContext=browser.newContext();var adminContext=browser.newContext()){
   var staff=staffContext.newPage();h.login(staff,"SolutionBrowserAgent");staff.navigate(h.base()+"/record/customer_case/"+id);staff.getByRole(AriaRole.LINK,new Page.GetByRoleOptions().setName("Customer resolution").setExact(true)).press("Enter");staff.getByLabel("Resolution code").selectOption("workaround");staff.getByLabel("Public solution").fill("Restart checkout <script>safe</script>\nThen retry your order.");ReleaseBrowserAcceptance.accessible(staff);staff.screenshot(new Page.ScreenshotOptions().setPath(Path.of("target/customer-resolution-propose-light.png")).setFullPage(true));CustomerCasesBrowserAcceptance.click(staff,"Propose customer solution");assertThat(staff.locator("main")).containsText("Pending");assertThat(staff.locator("main script")).hasCount(0);
   var customer=customerContext.newPage();customer.navigate(h.base()+"/login");customer.getByLabel("Username").fill("SolutionBrowserCustomer");customer.getByLabel("Password",new Page.GetByLabelOptions().setExact(true)).fill(WorkflowSupport.PASSWORD);customer.getByRole(AriaRole.BUTTON,new Page.GetByRoleOptions().setName("Enter your workspace")).press("Enter");customer.waitForURL("**/requests");customer.navigate(h.base()+"/record/customer_case/"+id);customer.getByRole(AriaRole.LINK,new Page.GetByRoleOptions().setName("Customer resolution").setExact(true)).press("Enter");assertThat(customer.locator("main")).containsText("Restart checkout <script>");customer.getByLabel("Your decision notes").fill("The issue still happens after restart");CustomerCasesBrowserAcceptance.click(customer,"Reject solution and resume support");assertThat(customer.locator("main")).containsText("Rejected");assertThat(customer.getByLabel("Public solution")).hasCount(0);
   staff.reload();staff.getByLabel("Public solution").fill("Apply the corrected checkout configuration\nConfirm the payment result before retrying.");staff.getByLabel("Resolution code").selectOption("solved");CustomerCasesBrowserAcceptance.click(staff,"Propose customer solution");customer.reload();CustomerCasesBrowserAcceptance.click(customer,"Dark mode");customer.setViewportSize(390,844);customer.getByLabel("Your decision notes").fill("Confirmed checkout is working now");ReleaseBrowserAcceptance.accessible(customer);customer.screenshot(new Page.ScreenshotOptions().setPath(Path.of("target/customer-resolution-review-dark.png")).setFullPage(true));CustomerCasesBrowserAcceptance.click(customer,"Accept solution and close case");assertThat(customer.locator("main")).containsText("Accepted");assertThat(customer.locator("main")).containsText("Proposal 1 · rejected");assertThat(customer.locator("main")).containsText("Proposal 2 · accepted");ReleaseBrowserAcceptance.accessible(customer);customer.screenshot(new Page.ScreenshotOptions().setPath(Path.of("target/customer-resolution-accepted-dark.png")).setFullPage(true));customer.getByRole(AriaRole.LINK,new Page.GetByRoleOptions().setName("Back to customer case")).press("Enter");assertThat(customer.locator("main")).containsText("Closed");
   var admin=adminContext.newPage();h.login(admin,"admin");admin.navigate(h.base()+"/record/customer_case/"+id+"/resolution");admin.getByLabel("Reopening reason").fill("Customer reported a separate regression");CustomerCasesBrowserAcceptance.click(admin,"Reopen accepted customer case");assertThat(admin.locator("main")).containsText("Administrator reopened this accepted case");staff.reload();assertThat(staff.getByLabel("Public solution")).isVisible();
  }
 }
}
